const item = $input.first().json;
const body = item.body || item;

function normCa(p) {
  if (!p) return '';
  const d = String(p).replace(/\D/g, '');
  if (d.length === 10) return '+1' + d;
  if (d.length === 11 && d.startsWith('1')) return '+' + d;
  if (String(p).startsWith('+')) return '+' + d;
  return d ? '+1' + d : '';
}

const phone = normCa(body.telephone || body.phone || body.phone_number);
if (!phone) throw new Error('telephone requis');

const provider = ($env.TELEPHONY_PROVIDER || 'vicidial').toLowerCase();
const odooUrl = ($env.ODOO_URL || 'https://intellixcrm.com').replace(/\/$/, '');

if (provider === 'twilio') {
  const sid = $env.TWILIO_ACCOUNT_SID;
  const auth = Buffer.from(`${sid}:${$env.TWILIO_AUTH_TOKEN}`).toString('base64');
  const from = $env.TWILIO_FROM_SOUMISSION || '+15817058118';
  const base = ($env.N8N_WEBHOOK_URL || '').replace(/\/$/, '');
  await this.helpers.httpRequest({
    method: 'POST',
    url: `https://api.twilio.com/2010-04-01/Accounts/${sid}/Calls.json`,
    headers: { Authorization: 'Basic ' + auth, 'Content-Type': 'application/x-www-form-urlencoded' },
    body: `To=${encodeURIComponent(phone)}&From=${encodeURIComponent(from)}&Url=${encodeURIComponent(base + '/soumission-qc/twilio/voice')}&StatusCallback=${encodeURIComponent(base + '/soumission-qc/event')}`,
  });
  return [{ json: { ok: true, telephone: phone, provider: 'twilio', campaign: $env.VICIDIAL_CAMPAIGN || 'DW_QCB2C' } }];
}

const res = await this.helpers.httpRequest({
  method: 'POST',
  url: odooUrl + '/doorway/api/soumission-qc/dial',
  body: {
    jsonrpc: '2.0',
    method: 'call',
    params: {
      tenant_api_key: $env.DOORWAY_TENANT_API_KEY,
      telephone: phone,
      prenom: body.prenom || body.nombre || body.name || '',
      partner_id: body.partner_id || body.lead_id || '',
    },
    id: Date.now(),
  },
  json: true,
  timeout: 30000,
});
const result = res.result || res;
return [{
  json: {
    telephone: phone,
    campaign: $env.VICIDIAL_CAMPAIGN || 'DW_QCB2C',
    provider: 'vicidial',
    ok: !!(result.ok || result.success),
    ...result,
  },
}];

const b = $input.first().json.body || $input.first().json;
const ev = {
  event_type: b.event_type || 'recording_ready',
  call_sid: b.call_sid || b.CallSid || b.uniqueid || '',
  from: b.from || b.From || '',
  to: b.to || b.To || '',
  recording_url: b.recording_url || b.RecordingUrl || b.recording_path || '',
  amd_result: (b.amd_result || b.AnsweredBy || 'unknown').toLowerCase(),
  duration_sec: parseInt(b.duration_sec || b.CallDuration || b.duration || 0, 10) || 0,
  provider: b.provider || 'vicidial',
  partner_id: b.partner_id || b.lead_id || '',
  prenom: b.prenom || b.nombre || b.first_name || '',
  raw: b,
};

const base = ($env.N8N_WEBHOOK_URL || '').replace(/\/$/, '');
const engine = await this.helpers.httpRequest({
  method: 'POST',
  url: base + '/soumission-qc/conversation',
  body: ev,
  json: true,
});
const out = engine && engine.action ? engine : (Array.isArray(engine) ? engine[0] : { normalized: ev, engine });

if (ev.event_type === 'call_ended' || out.action === 'hangup') {
  const odooUrl = ($env.ODOO_URL || 'https://intellixcrm.com').replace(/\/$/, '');
  const cp = out.crm_payload || {};
  try {
    await this.helpers.httpRequest({
      method: 'POST',
      url: odooUrl + '/doorway/api/soumission-qc/call-ended',
      body: {
        jsonrpc: '2.0',
        method: 'call',
        params: { tenant_api_key: $env.DOORWAY_TENANT_API_KEY, ...cp },
        id: Date.now(),
      },
      json: true,
      timeout: 15000,
    });
  } catch (e) {
    out.odoo_error = (e.message || String(e)).slice(0, 200);
  }
  if (cp.crm_action === 'tag_lead_qualifie') {
    try {
      await this.helpers.httpRequest({
        method: 'POST',
        url: base + '/soumission-qc/qualified',
        body: cp,
        json: true,
      });
    } catch (_e) { /* qualified wf */ }
  } else if (cp.crm_action) {
    try {
      await this.helpers.httpRequest({
        method: 'POST',
        url: base + '/soumission-qc/non-qualified',
        body: cp,
        json: true,
      });
    } catch (_e) { /* non-qualified wf */ }
  }
}
return [{ json: out }];

/**
 * Sofia — Soumission Entrepreneurs (Québec fr-CA)
 * Répliques fixes — pré-générer en MP3 : STORAGE_BUCKET_URL/{key}.mp3
 */
const REPLIQUES = {
  sofia_ouverture:
    'Bonjour ! Je m\'appelle Sofia, je vous appelle de Soumission Entrepreneurs. ' +
    'J\'ai juste une petite question rapide — êtes-vous bien propriétaire de votre maison ?',

  sofia_q1_clarif:
    'Pas de problème, je reformule : est-ce que la maison est à votre nom, ou vous êtes locataire ?',

  sofia_exit_locataire:
    'Pas de souci du tout ! Bonne journée et merci pour votre temps !',

  sofia_q2_age:
    'Super ! Votre maison a à peu près quel âge ? Moins de dix ans, entre dix et trente ans, ou plus de trente ans ?',

  sofia_q3_travaux:
    'Parfait, merci ! Y a-t-il des travaux dont vous auriez besoin en ce moment — ' +
    'toiture, fenêtres, salle de bain, cuisine, ou autre chose ?',

  sofia_q4_vente:
    'Je comprends ! Est-ce que vous pensez vendre votre maison dans les trois prochaines années ?',

  sofia_exit_pas_projet:
    'Très bien ! On pourra vous recontacter si ça change. Bonne journée !',

  sofia_q5_pitch:
    'Excellente nouvelle ! Il existe des subventions gouvernementales auxquelles vous avez peut-être droit. ' +
    'Notre directeur des travaux fait des visites gratuites — il évalue votre projet, trouve des soumissions ' +
    'd\'entrepreneurs certifiés et vérifie les subventions qui s\'appliquent. ' +
    'Ça vous intéresserait qu\'il vous rappelle cette semaine ?',

  sofia_q5_objection:
    'Je comprends tout à fait ! C\'est vraiment sans engagement — juste cinq minutes pour voir ce qui s\'applique chez vous. ' +
    'Vous n\'avez rien à perdre et peut-être des milliers de dollars à récupérer ! Qu\'est-ce qui vous retient ?',

  sofia_q6_preference:
    'Super ! C\'est quoi le meilleur moment pour vous joindre — plutôt en avant-midi ou en après-midi ?',

  sofia_q7_closing:
    'Parfait ! Notre directeur des travaux va vous appeler bientôt. ' +
    'Vous allez recevoir un texto de confirmation dans quelques minutes. Bonne journée et à très bientôt !',

  sofia_exit_pas_interesse:
    'Pas de problème ! Bonne journée et à peut-être une prochaine fois !',

  sofia_exit_polite: 'Merci beaucoup pour votre temps. Bonne journée !',
  sofia_exit_dnc: 'C\'est noté, on vous retire de notre liste. Bonne journée !',
  sofia_fallback: 'Désolée, je n\'ai pas bien entendu. Pouvez-vous répéter s\'il vous plaît ?',
  sofia_repondeur:
    'Bonjour, c\'est Sofia de Soumission Entrepreneurs. Votre maison pourrait être admissible ' +
    'à des subventions pour des travaux. On vous rappelle bientôt. Merci !',
  sofia_exit_timeout: 'Je vois que vous êtes occupé — on vous rappellera une autre fois. Bonne journée !',
};

const DEEPGRAM_CONFIG = {
  model: 'nova-2',
  language: 'fr-CA',
  endpointing: 300,
  utterance_end_ms: 500,
  interim_results: true,
  smart_format: true,
  punctuate: true,
  encoding: 'mulaw',
  sample_rate: 8000,
};

function audioUrl(key) {
  const bucket = ($env.STORAGE_BUCKET_URL || '').replace(/\/$/, '');
  return bucket ? `${bucket}/${key}.mp3` : '';
}

function computeCost(durationSec, amdResult) {
  const amd = (amdResult || '').toLowerCase();
  if (['machine', 'not_sure', 'fax'].includes(amd)) {
    return { cost: 0, billed: false, reason: 'AMD_DETECTED' };
  }
  const sec = Math.max(0, parseInt(durationSec, 10) || 0);
  if (!sec) return { cost: 0, billed: false, reason: 'ZERO_DURATION' };
  const rate = parseFloat($env.SOFIA_QC_RATE_PER_MIN || '0.25') / 60;
  return { cost: Math.round(sec * rate * 10000) / 10000, billed: true, duration: sec };
}

/**
 * Classification rapide fr-CA — évite appel LLM sur réponses courantes.
 */
function normTranscript(t) {
  return (t || '')
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/[^a-z0-9\s]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function fastClassifyIntent(etape, transcript) {
  const t = normTranscript(transcript);
  if (!t) return null;

  const affirm =
    /^(oui|ouais|ouin|yes|ok|correct|exact|c est ca|cest ca|bien sur)\b/.test(t) ||
    /\b(oui|ouais|ouin|bien sur|exactement|correct|c est ca)\b/.test(t);
  const deny =
    /^(non|nan|nope|no)\s*$/.test(t) ||
    /\b(non je|pas proprietaire|pas proprio|locataire|je loue|en location|je suis locataire)\b/.test(t);
  const owner =
    /\b(proprietaire|proprio|a mon nom|c est ma maison|maison est a moi|titulaire)\b/.test(t);
  const tenant = /\b(locataire|je loue|en location|pas proprietaire|pas proprio)\b/.test(t);
  const pasInteresse = /\b(pas interesse|pas interesse|ca m interesse pas|laissez moi|rappelez plus)\b/.test(t);
  const dnc = /\b(ne plus appeler|retirez|retirer|do not call|enlevez mon numero)\b/.test(t);
  const unsure = /\b(je sais pas|sais pas|pas sur|peut etre|je pense)\b/.test(t);

  if (etape === 'ouverture' || etape === 'Q1_clarif') {
    if (tenant || (deny && !owner)) return { intent: 'non' };
    if (owner || affirm) return { intent: 'oui' };
    if (pasInteresse) return { intent: 'pas_interesse' };
    if (dnc) return { intent: 'do_not_call' };
    if (unsure) return { intent: 'incertain' };
  }

  if (etape === 'Q2_age') {
    if (/\b(moins de 10|neuve|recente|moins de dix)\b/.test(t)) return { intent: 'ok', valeur: 'moins_10' };
    if (/\b(10 et 30|dix et trente|entre 10|entre dix)\b/.test(t)) return { intent: 'ok', valeur: '10_30' };
    if (/\b(plus de 30|plus de trente|vieille|ancienne)\b/.test(t)) return { intent: 'ok', valeur: 'plus_30' };
    if (affirm) return { intent: 'ok', valeur: t.slice(0, 40) };
  }

  if (etape === 'Q3_travaux') {
    if (/\b(rien|aucun|pas de travaux|rien pour l instant|ca va bien)\b/.test(t)) return { intent: 'aucun' };
    const trav = t.match(/\b(toiture|fenetre|fenetres|cuisine|salle de bain|sdb|sous sol|patio|thermopompe|isolation)\b/);
    if (trav) return { intent: 'ok', valeur: trav[1] };
    if (affirm && t.length > 8) return { intent: 'ok', valeur: t.slice(0, 60) };
  }

  if (etape === 'Q4_vente') {
    if (affirm && !deny) return { intent: 'oui' };
    if (deny) return { intent: 'non' };
  }

  if (['Q5_pitch', 'Q5_objection'].includes(etape)) {
    if (affirm && !deny) return { intent: 'oui' };
    if (deny || pasInteresse) return { intent: 'non' };
    if (unsure) return { intent: 'incertain' };
  }

  if (etape === 'Q6_preference') {
    if (/\b(avant midi|matin|matinee|am|avant-midi)\b/.test(t)) return { intent: 'ok', valeur: 'avant_midi' };
    if (/\b(apres midi|apres-midi|pm|soir|apres-midi)\b/.test(t)) return { intent: 'ok', valeur: 'apres_midi' };
    if (affirm) return { intent: 'ok', valeur: t.slice(0, 40) };
  }

  if (pasInteresse) return { intent: 'pas_interesse' };
  if (dnc) return { intent: 'do_not_call' };
  return null;
}

const A = {
  ouverture: audioUrl('sofia_ouverture'),
  q1: audioUrl('sofia_q1_clarif'),
  q2: audioUrl('sofia_q2_age'),
  q3: audioUrl('sofia_q3_travaux'),
  q4: audioUrl('sofia_q4_vente'),
  q5: audioUrl('sofia_q5_pitch'),
  q5b: audioUrl('sofia_q5_objection'),
  q6: audioUrl('sofia_q6_preference'),
  q7: audioUrl('sofia_q7_closing'),
  exit_loc: audioUrl('sofia_exit_locataire'),
  exit_projet: audioUrl('sofia_exit_pas_projet'),
  exit_pi: audioUrl('sofia_exit_pas_interesse'),
  exit_polite: audioUrl('sofia_exit_polite'),
  exit_dnc: audioUrl('sofia_exit_dnc'),
  fallback: audioUrl('sofia_fallback'),
  timeout: audioUrl('sofia_exit_timeout'),
};

const _raw = $input.first().json;
const ev = (_raw && _raw.body && typeof _raw.body === 'object') ? _raw.body : _raw;

if (ev.event_type === 'amd_result' && ['machine', 'fax', 'not_sure'].includes((ev.amd_result || '').toLowerCase())) {
  return [{ json: {
    action: 'hangup', call_sid: ev.call_sid, qualified: false, statut: 'messagerie',
    crm_action: null, event: ev,
  } }];
}

function buildCrmPayload(session, ev, opts) {
  const phone = session?.data?.telephone || session?.telephone || ev.to || ev.from || '';
  if (!phone || !session) return null;
  const d = session.data || {};
  return {
    call_sid: ev.call_sid || '',
    partner_id: ev.partner_id || ev.lead_id || '',
    prenom: d.prenom || ev.prenom || ev.nombre || '',
    telephone: phone,
    qualified: !!(opts && opts.qualified),
    statut: (opts && opts.statut) || session.crm_action || 'en_cours',
    crm_action: session.crm_action || null,
    age_maison: d.age_maison || '',
    travaux: d.travaux || '',
    vente_prevue: d.vente_prevue,
    preference_rappel: d.preference_rappel || '',
    transcript: (session.transcript_log || []).join('\n'),
    recording_url: ev.recording_url || '',
    duration_sec: session.duree_sec || ev.duration_sec || 0,
    campaign: $env.CAMPAIGN_ID || 'sofia-soumission-qc-2026',
  };
}

if (ev.event_type === 'call_ended' || ev.action === 'hangup') {
  const sd = $getWorkflowStaticData('global');
  const session = (sd.sofia_qc_sessions || {})[ev.call_sid];
  const crm_payload = session ? buildCrmPayload(session, ev, {
    qualified: session.crm_action === 'tag_lead_qualifie',
    statut: session.crm_action || 'non_qualifie',
  }) : null;
  return [{ json: { action: 'hangup', call_sid: ev.call_sid, crm_payload, session, event: ev } }];
}

const callSid = ev.call_sid || '';
const sd = $getWorkflowStaticData('global');
if (!sd.sofia_qc_sessions) sd.sofia_qc_sessions = {};
let session = sd.sofia_qc_sessions[callSid];

if (!session) {
  session = {
    etape: 'ouverture',
    telephone: ev.to || ev.from || '',
    prenom: ev.prenom || ev.nombre || '',
    duree_sec: 0,
    hors_sujet_count: 0,
    silence_count: 0,
    soft_limit: parseInt($env.AGENT_SOFT_LIMIT_SEC || '170', 10),
    crm_action: null,
    data: {
      prenom: ev.prenom || ev.nombre || '',
      proprietaire: null,
      age_maison: null,
      travaux: null,
      vente_prevue: null,
      preference_rappel: null,
      telephone: ev.to || ev.from || '',
    },
    transcript_log: [],
  };
  sd.sofia_qc_sessions[callSid] = session;
}

if (ev.event_type === 'call_start' || (!ev.recording_url && session.etape === 'ouverture' && !ev.event_type)) {
  return [{ json: {
    action: 'play_audio', audio_url: A.ouverture, call_sid: callSid,
    qualified: false, statut: 'en_cours', session, event: ev,
  } }];
}

if (ev.event_type !== 'recording_ready' || !ev.recording_url) {
  return [{ json: { action: 'hangup', error: 'no_recording', event: ev } }];
}

let transcript = '';
let classification = { intent: 'silence' };
const odooBase = ($env.ODOO_URL || 'https://intellixcrm.com').replace(/\/$/, '');

try {
  const sttRes = await this.helpers.httpRequest({
    method: 'POST',
    url: odooBase + '/api/renov/stt/deepgram',
    headers: { 'Content-Type': 'application/json', 'X-Renov-Stt-Key': ($env.SOFIA_STT_WEBHOOK_KEY || 'doorway-sofia-stt') },
    body: { recording_url: ev.recording_url, language: 'fr-CA' },
    json: true,
    timeout: 25000,
  });
  transcript = (sttRes && sttRes.transcript) || '';
} catch (e) {
  transcript = '';
}

const fast = fastClassifyIntent(session.etape, transcript);
if (fast) {
  classification = fast;
} else if (transcript.trim()) {
  const sys = `Classificateur JSON fr-CA Soumission Entrepreneurs. Étape: ${session.etape}. JSON seulement.
ouverture/Q1_clarif: oui|non|incertain|pas_interesse|do_not_call|silence
Q2_age: {intent:ok,valeur:moins_10|10_30|plus_30}
Q3_travaux: {intent:ok,valeur:...}|aucun|silence
Q4_vente: oui|non|silence
Q5_pitch/Q5_objection: oui|non|incertain|silence
Q6_preference: {intent:ok,valeur:avant_midi|apres_midi}`;
  try {
    const cl = await this.helpers.httpRequest({
      method: 'POST',
      url: 'https://api.anthropic.com/v1/messages',
      headers: { 'x-api-key': $env.ANTHROPIC_API_KEY, 'anthropic-version': '2023-06-01', 'Content-Type': 'application/json' },
      body: {
        model: $env.CLAUDE_MODEL || 'claude-3-5-haiku-20241022',
        max_tokens: 80,
        system: sys,
        messages: [{ role: 'user', content: `Transcription: "${transcript}"` }],
      },
      json: true,
      timeout: 12000,
    });
    const txt = (cl.content && cl.content[0] && cl.content[0].text) || '{}';
    const m = txt.match(/\{[\s\S]*\}/);
    classification = JSON.parse(m ? m[0] : txt);
  } catch (_e) {
    classification = { intent: 'silence' };
  }
}

let intent = classification.intent || 'silence';
const valeur = classification.valeur || '';
const etape = session.etape;
session.transcript_log.push(`[${etape}] ${transcript || '(silence)'} → ${intent}${valeur ? '/' + valeur : ''}`);
session.duree_sec += Math.max(4, parseInt(ev.duration_sec, 10) || 6);

let route = { hangup: false, qualified: false, audioUrl: A.fallback, crm_action: null };

if (session.duree_sec >= session.soft_limit) {
  route = { hangup: true, audioUrl: A.timeout, crm_action: null };
} else if (intent === 'do_not_call') {
  route = { hangup: true, audioUrl: A.exit_dnc, crm_action: 'tag_dnc' };
} else if (intent === 'pas_interesse' || intent === 'refus') {
  route = { hangup: true, audioUrl: A.exit_pi, crm_action: 'tag_pas_interesse' };
} else if (intent === 'silence') {
  session.silence_count += 1;
  if (etape === 'ouverture') session.etape = 'Q1_clarif';
  route = { hangup: false, audioUrl: etape === 'ouverture' ? A.q1 : A.fallback };
} else {
  session.silence_count = 0;
  if (etape === 'ouverture' || etape === 'Q1_clarif') {
    if (intent === 'oui') {
      session.data.proprietaire = true;
      session.etape = 'Q2_age';
      route = { hangup: false, audioUrl: A.q2 };
    } else if (intent === 'non') {
      route = { hangup: true, audioUrl: A.exit_loc, crm_action: 'tag_locataire' };
    } else {
      session.etape = 'Q1_clarif';
      route = { hangup: false, audioUrl: A.q1 };
    }
  } else if (etape === 'Q2_age' && intent === 'ok') {
    session.data.age_maison = valeur;
    session.etape = 'Q3_travaux';
    route = { hangup: false, audioUrl: A.q3 };
  } else if (etape === 'Q3_travaux') {
    if (intent === 'aucun') {
      session.data.travaux = '';
      session.etape = 'Q4_vente';
      route = { hangup: false, audioUrl: A.q4 };
    } else if (intent === 'ok') {
      session.data.travaux = valeur || transcript.slice(0, 80);
      session.crm_action = 'tag_travaux';
      session.etape = 'Q5_pitch';
      route = { hangup: false, audioUrl: A.q5 };
    }
  } else if (etape === 'Q4_vente') {
    if (intent === 'oui') {
      session.data.vente_prevue = true;
      session.etape = 'Q5_pitch';
      route = { hangup: false, audioUrl: A.q5 };
    } else {
      route = { hangup: true, audioUrl: A.exit_projet, crm_action: 'tag_pas_projet' };
    }
  } else if (etape === 'Q5_pitch') {
    if (intent === 'oui') {
      session.etape = 'Q6_preference';
      route = { hangup: false, audioUrl: A.q6 };
    } else if (intent === 'incertain' || intent === 'non') {
      session.etape = 'Q5_objection';
      route = { hangup: false, audioUrl: A.q5b };
    }
  } else if (etape === 'Q5_objection') {
    if (intent === 'oui') {
      session.etape = 'Q6_preference';
      route = { hangup: false, audioUrl: A.q6 };
    } else {
      route = { hangup: true, audioUrl: A.exit_pi, crm_action: 'tag_pas_interesse' };
    }
  } else if (etape === 'Q6_preference' && intent === 'ok') {
    session.data.preference_rappel = valeur;
    session.etape = 'Q7_closing';
    session.crm_action = 'tag_lead_qualifie';
    route = { hangup: true, qualified: true, audioUrl: A.q7, crm_action: 'tag_lead_qualifie' };
  }
}

session.crm_action = route.crm_action || session.crm_action;
sd.sofia_qc_sessions[callSid] = session;

const crm_payload = route.hangup
  ? buildCrmPayload(session, ev, { qualified: route.qualified, statut: session.crm_action || 'non_qualifie' })
  : null;

return [{
  json: {
    action: route.hangup ? 'hangup' : 'play_audio',
    audio_url: route.audioUrl,
    call_sid: callSid,
    qualified: !!route.qualified,
    crm_action: session.crm_action,
    crm_payload,
    transcript,
    statut: session.crm_action || 'en_cours',
    session,
    event: ev,
  },
}];

const p = $input.first().json.body || $input.first().json;
const phone = p.telephone || p.phone || '';
const prenom = p.prenom || (p.nom || '').split(' ')[0] || 'Bonjour';
const jour = p.jour || 'cette semaine';
const moment = p.preference_rappel === 'avant_midi' ? 'avant-midi' : 'après-midi';

const msg =
  `Bonjour ${prenom} ! 😊\nMerci pour votre temps.\n` +
  `Notre directeur des travaux vous contactera ${jour} en ${moment}.\n` +
  `Des questions ? Répondez à ce message !\n— Soumission Entrepreneurs`;

if (!phone) return [{ json: { ok: false, error: 'no_phone' } }];

const sid = $env.TWILIO_ACCOUNT_SID;
const auth = Buffer.from(`${sid}:${$env.TWILIO_AUTH_TOKEN}`).toString('base64');
const from = $env.TWILIO_FROM_SOUMISSION || '+15817058118';

await this.helpers.httpRequest({
  method: 'POST',
  url: `https://api.twilio.com/2010-04-01/Accounts/${sid}/Messages.json`,
  headers: { Authorization: 'Basic ' + auth, 'Content-Type': 'application/x-www-form-urlencoded' },
  body: `To=${encodeURIComponent(phone)}&From=${encodeURIComponent(from)}&Body=${encodeURIComponent(msg)}`,
});

const odooUrl = ($env.ODOO_URL || 'https://intellixcrm.com').replace(/\/$/, '');
let odoo = {};
try {
  const res = await this.helpers.httpRequest({
    method: 'POST',
    url: odooUrl + '/doorway/api/soumission-qc/qualified',
    body: {
      jsonrpc: '2.0',
      method: 'call',
      params: { tenant_api_key: $env.DOORWAY_TENANT_API_KEY, ...p },
      id: Date.now(),
    },
    json: true,
  });
  odoo = res.result || res;
} catch (e) {
  odoo = { error: (e.message || String(e)).slice(0, 200) };
}

return [{ json: { ok: true, sms_sent: true, odoo } }];

const p = $input.first().json.body || $input.first().json;
const action = p.crm_action || p.statut || '';

const odooUrl = ($env.ODOO_URL || 'https://intellixcrm.com').replace(/\/$/, '');
let odoo = {};
try {
  const res = await this.helpers.httpRequest({
    method: 'POST',
    url: odooUrl + '/doorway/api/soumission-qc/non-qualified',
    body: {
      jsonrpc: '2.0',
      method: 'call',
      params: { tenant_api_key: $env.DOORWAY_TENANT_API_KEY, ...p, crm_action: action },
      id: Date.now(),
    },
    json: true,
  });
  odoo = res.result || res;
} catch (e) {
  odoo = { error: (e.message || String(e)).slice(0, 200) };
}

return [{ json: { ok: true, action, odoo } }];

const today = new Date().toISOString().slice(0, 10);
const odooUrl = ($env.ODOO_URL || 'https://intellixcrm.com').replace(/\/$/, '');

let stats = { date: today, calls: 0, qualified: 0, pas_interesse: 0, locataire: 0, pas_projet: 0 };
try {
  const res = await this.helpers.httpRequest({
    method: 'POST',
    url: odooUrl + '/doorway/api/soumission-qc/daily-stats',
    body: {
      jsonrpc: '2.0',
      method: 'call',
      params: { tenant_api_key: $env.DOORWAY_TENANT_API_KEY, date: today },
      id: Date.now(),
    },
    json: true,
  });
  stats = { ...stats, ...(res.result || res) };
} catch (_e) { /* stats optional */ }

const pct = stats.calls ? Math.round((stats.qualified / stats.calls) * 100) : 0;
const body =
  `Rapport Sofia — ${today}\n` +
  `📞 Appels : ${stats.calls}\n` +
  `✅ Qualifiés : ${stats.qualified} (${pct}%)\n` +
  `❌ Pas intéressés : ${stats.pas_interesse}\n` +
  `🏠 Locataires : ${stats.locataire}\n` +
  `📋 Sans projet : ${stats.pas_projet}`;

const email = $env.MANAGER_EMAIL || $env.DIRECTOR_EMAIL;
if (email) {
  try {
    await this.helpers.httpRequest({
      method: 'POST',
      url: odooUrl + '/doorway/api/soumission-qc/send-report',
      body: {
        jsonrpc: '2.0',
        method: 'call',
        params: { tenant_api_key: $env.DOORWAY_TENANT_API_KEY, email, subject: `Rapport Sofia SE — ${today}`, body },
        id: Date.now(),
      },
      json: true,
    });
  } catch (_e) { /* email optional */ }
}

return [{ json: { ok: true, stats, report: body } }];
